from gen import *
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares

def latest(): return pickle.load(open('/app/output/latest.pkl','rb'))
def state(o=None): return np.array((o or latest()).meta['proprio']['now'])
def brief(o):
 p=state(o); print('time',o.meta['time_left_s'],'base',p[:4], 'q',p[4:11],'eef',p[26:29], 'fingers',p[11:13])
def record(o,name):
 o.save('/app/output/'+name);pickle.dump(o,open('/app/output/latest.pkl','wb')); brief(o)
def act(q=None,grip=None,base=None,torso=0,seconds=2,name='move'):
 p=state(); a=p[29:42].copy(); a[8:12]=0
 if q is not None: a[:7]=q
 if grip is not None: a[7]=grip
 if base is not None: a[8:11]=base
 a[11]=torso;a[12]=1 if base is not None else -1
 n=round(seconds/.05); A=np.tile(a,(n,1)); A[:,:7]=np.linspace(p[29:36],a[:7],n)
 o=r.submit('joint_position',A,include_depth=True,video='none'); record(o,name);return o

def point(cam,u,v,o=None):
 o=o or latest(); d=o.depth[cam]; d=d[-1] if d.ndim==3 else d
 z=float(d[v,u]); k=np.array(o.meta['cameras'][cam]['intrinsic_cv']); M=np.array(o.meta['cameras'][cam]['cam2world_gl']);return M[:3,:3]@np.array([(u-k[0,2])*z/k[0,0],-(v-k[1,2])*z/k[1,1],-z])+M[:3,3]
def fk(q):
 origins=[([0,0,.333],[0,0,0]),([0,0,0],[-np.pi/2,0,0]),([0,-.316,0],[np.pi/2,0,0]),([.0825,0,0],[np.pi/2,0,0]),([-.0825,.384,0],[-np.pi/2,0,0]),([0,0,0],[np.pi/2,0,0]),([.088,0,0],[np.pi/2,0,0])]
 T=np.eye(4)
 for a,(xyz,rpy) in zip(q,origins):
  M=np.eye(4);M[:3,3]=xyz;M[:3,:3]=Rot.from_euler('xyz',rpy).as_matrix()@Rot.from_euler('z',a).as_matrix();T=T@M
 return T
if __name__=='__main__':
 o=latest();p=state(o); print('FK',fk(p[4:11]));
 for cam,uvs in [('robot0_agentview_left',[(157,100),(157,140),(181,135)]),('robot0_agentview_center',[(115,105),(117,150)])]:
  for u,v in uvs: print(cam,u,v,point(cam,u,v))
PY
